def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blues = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    endpoints = []
    for r, c in blues:
        neighbors = [(dr, dc) for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1))
                     if (r + dr, c + dc) in blues]
        if len(neighbors) == 1:
            endpoints.append((r, c, -neighbors[0][0], -neighbors[0][1]))
    if not endpoints:
        return out
    r, c, dr, dc = max(endpoints, key=lambda p: p[0] + p[1])
    for _ in range(h * w * 4):
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            break
        if grid[nr][nc] == 2:
            dr = -dr
        elif grid[nr][nc] == 3:
            dc = -dc
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            break
        out[nr][nc] = 1
        r, c = nr, nc
    return out
